# owner: platform
"""Weekly timesheet rows built from a list of shifts."""

from typing import Iterable, List

from hourglass.models import Shift


def _totals(shifts: List[Shift]) -> dict:
    """Shift count and minutes per worker, rejecting blank names."""
    totals = {}
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("shift has a blank worker name")
        count, mins = totals.get(shift.worker, (0, 0))
        totals[shift.worker] = (count + 1, mins + shift.span.minutes)
    return totals


def _busiest(entry) -> tuple:
    """Sort key: most minutes first, then name."""
    return (-entry[1][1], entry[0])


def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, like Brisa: 3 shifts, 12.5 hours, busiest first."""
    totals = _totals(list(shifts))
    if not totals:
        raise ValueError("no shifts to total")
    ranked = sorted(totals.items(), key=_busiest)
    return [f"{name}: {count} shifts, {mins / 60:.1f} hours" for name, (count, mins) in ranked]
